package pe.nexo.store.order;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import pe.nexo.store.order.dto.*;@RestController@RequestMapping("/api/orders")public class OrderController{private final OrderService service;public OrderController(OrderService service){this.service=service;}@PostMapping public ResponseEntity<OrderResponse>create(@Valid@RequestBody CreateOrderRequest request){return ResponseEntity.status(HttpStatus.CREATED).body(service.create(request));}@GetMapping("/{number}")public OrderResponse find(@PathVariable String number){return service.findByNumber(number);}}
